; friction.asm -- chapter 10: WHERE IT BREAKS: a speed halved with SRA
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "friction.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
v1      EQU RAM_START          ; three speeds
v2      EQU RAM_START + 1
v3      EQU RAM_START + 2
list1   EQU RAM_START + $10    ; and the speeds after each halving
list2   EQU RAM_START + $20
list3   EQU RAM_START + $30
        ld a, 100
        ld (v1), a
        ld a, -100
        ld (v2), a
        ld (v3), a
        ld hl, list1
        ld de, list2
        ld ix, list3
        ld b, 10
halve:  ld a, (v1)
        sra a                   ; half, keeping the sign
        ld (v1), a
        ld (hl), a
        inc hl
        ld a, (v2)
        sra a
        ld (v2), a
        ld (de), a
        inc de
        ld a, (v3)
        bit 7, a                ; negative?
        jr z, v3pos
        inc a                   ; then one nearer to 0 first
v3pos:  sra a
        ld (v3), a
        ld (ix+0), a
        inc ix
        djnz halve
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
